const fs = require('fs');
const path = require('path');

// 1. Copy root public files from dist to public
const distDir = 'dist';
const publicDir = 'public';
if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });

const publicFiles = [
  'Gilroy-Medium.ttf',
  'NeueMachina-Regular.otf',
  'favicon.avif',
  'favicon.png',
  'favicon.webp',
  'hero-bot.png',
  'hero-bot.webp',
  'hero-mid.png',
  'hero-mid.webp',
  'llms.txt',
  'robots.txt',
  'sitemap.xml'
];

publicFiles.forEach(f => {
  const src = path.join(distDir, f);
  const dest = path.join(publicDir, f);
  if (fs.existsSync(src)) {
    fs.copyFileSync(src, dest);
    console.log('Copied to public:', f);
  }
});

// 2. Copy and un-hash assets from dist/assets to src/assets
const distAssetsDir = path.join('dist', 'assets');
const srcAssetsDir = path.join('src', 'assets');
if (!fs.existsSync(srcAssetsDir)) fs.mkdirSync(srcAssetsDir, { recursive: true });

if (fs.existsSync(distAssetsDir)) {
  const files = fs.readdirSync(distAssetsDir);
  files.forEach(f => {
    // Check if it is an image/asset (not js/css/map)
    if (/\.(webp|avif|png|jpg|jpeg|svg|gif|otf|ttf|woff|woff2)$/i.test(f)) {
      // Un-hash e.g. doc-auth-ratelimit-DUUHf8VO.webp -> doc-auth-ratelimit.webp
      const unhashed = f.replace(/-[A-Za-z0-9_-]{8}\./, '.');
      const src = path.join(distAssetsDir, f);
      const dest = path.join(srcAssetsDir, unhashed);
      fs.copyFileSync(src, dest);
      console.log('Copied & unhashed to src/assets:', f, '->', unhashed);
    }
  });
}
"

