      links: [
        { label: 'Launch Explore', href: '/dashboard' },
        { label: 'Feature overview', href: '/docs' },
      ],
    },
    {
      id: 'repository-intelligence',
      image: gitImage3,
      title: 'Repository Intelligence',
      badge: 'Analytics',
      description:
